{
  "scenes": [
    {
      "scene_id": "S1",
      "name": "杂乱桌面全景",
      "intent": "建立问题场景，让观众代入"
    },
    {
      "scene_id": "S2",
      "name": "三个动作演示",
      "intent": "清晰可执行地展示整理步骤"
    },
    {
      "scene_id": "S3",
      "name": "整理后画面与收尾",
      "intent": "呈现对比结果，落回专注力"
    }
  ],
  "shots": [
    {
      "shot_id": "SH01",
      "scene": "S1",
      "description": "俯拍杂乱的桌面特写，纸、便签、水杯、充电线交错，镜头缓慢推进 2 秒。"
    },
    {
      "shot_id": "SH02",
      "scene": "S2",
      "description": "主观视角，双手把视线正前方的杂物推到侧边，只留一台笔记本，画面留白变多。"
    },
    {
      "shot_id": "SH03",
      "scene": "S2",
      "description": "手部特写：水杯放到桌面左上角固定位置，充电线绕好放进固定小盒，一次一个动作不剪辑跳跃。"
    },
    {
      "shot_id": "SH04",
      "scene": "S2",
      "description": "纸和便签分成两堆，左边留桌上，右边推进抽屉并关合，用三十秒快剪完成。"
    },
    {
      "shot_id": "SH05",
      "scene": "S3",
      "description": "与 SH01 同一机位的对比镜头，桌面干净，人坐下打开笔记本开始工作。"
    },
    {
      "shot_id": "SH06",
      "scene": "S3",
      "description": "人物正面半身镜头，正面光，字幕打出"三分钟，减少干扰"，定格收尾。"
    }
  ]
}

